import type { AgentRuntimeContextService } from './agent-runtime';

export async function buildAgentRuntimeContext(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: {
    workspaceId: string;
    channel: string;
    message: string;
    contactId?: string;
    allowedTools?: string[];
  },
): Promise<{ systemPromptBlock: string }> {
  if (!agentRuntime) {
    return { systemPromptBlock: '' };
  }
  return agentRuntime.buildContext(params);
}

export async function recordAgentRuntimeTurn(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: {
    workspaceId: string;
    channel: string;
    userMessage: string;
    assistantMessage?: string;
    contactId?: string;
    intent?: string;
    confidence?: number;
    actions?: Array<{ toolName: string; success: boolean; result?: unknown }>;
  },
): Promise<void> {
  await agentRuntime?.recordTurnOutcome(params);
}

export function buildAgentToolEnvelope(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: {
    workspaceId: string;
    toolName: string;
  },
): { id: string; toolName: string; allowed: boolean } {
  return (
    agentRuntime?.buildToolEnvelope(params) ?? {
      id: 'agent-runtime-unavailable',
      toolName: params.toolName,
      allowed: true,
    }
  );
}

